parts.append(section('history','開發過程與版本沿革','Process and version history',table([bi('階段','Stage'),bi('留存成果','Retained results')],[[bi('單頁原型','Single-page prototypes'),bi('bird-image-map.html／second-story-image-map.html 保存場景、熱區、停留時間。','bird-image-map.html / second-story-image-map.html retain scene, hotspots and dwell-time references.')],[bi('資料與模組化','Data and modules'),bi('章節 CSV → birds.json／levels；拆分鏡頭、攝影、停留、輸入、收音。','Chapter CSV → birds.json / levels; separate camera, capture, presence, input and audio.')],['v0.3',bi('十關彩鉛、MIDI 配樂、可關閉合成鳥鳴。','Pencil assets for ten levels, MIDI and synthesized ambience.')],['v0.4',bi('第 1–6 關童書插畫、音量、三種操控、一鍵與失敗格校正。','Picture-book assets for levels 1–6, volume, three input modes, guided calibration and retries.')],['v0.4.5',bi('第 7–10 關童書插畫完成，十關共 228 張；EXE／APK 有發行 hash。','Picture-book assets for levels 7–10, 228 total; releases have recorded EXE / APK hashes.')],['2026-10-11',bi('本次 Codex：5 種錄音、按關卡選播、低通、取消備援、雙語文件、STEM agent；修正三關換鏡頭提示。','This Codex delivery: five recordings, level matching, low-pass, cancellation / fallback, bilingual report and STEM agent; corrected equipment hints in three levels.')]])+para('流程從 README、release 文件與素材紀錄重建，不是完整提交或聊天歷史；未把缺乏證據的實作歸屬到特定 AI。','Reconstructed from README, release documents and asset records; not a full commit or chat history. Implementations without evidence are not attributed to specific AI models.')))
parts.append(section('agents','多 agent 與不同 AI 協作','Multiple agents and AI collaboration',table([bi('工具／角色','Tool / role'),bi('證據','Evidence'),bi('可確認與限制','What is established / limits')],[['DeepSeek Harness','<a href="motionpad-game-creator/README.md">README</a> · agent.cordis.yml',bi('既有 agent preset 與技能編排；不能確認歷次實際模型版本。','Existing agent preset and skill composition, not the model version used in each historical call.')],['Claude','<a href=".claude/launch.json">launch.json</a>',bi('可確認啟動設定，不能證明特定功能由 Claude 撰寫。','Confirms launch configuration, not authorship of a feature.')],['imagegen','<a href="assets/pencil-cartoon/GENERATION-PROMPTS.md">GENERATION-PROMPTS</a> · manifest · REVIEW',bi('逐張風格轉換提示、素材狀態與驗收；早期呼叫未全數留存。','Per-image style-transfer prompts, asset states and review; not all early calls were retained.')],[bi('不同 agent 接續','Agent handoffs'),'<a href="assets/pencil-cartoon/README.md">pencil-cartoon README</a>',bi('素材準備與接入由不同工作維護，文件有後續 agent 流程；名稱／ID 不完整。','Preparation and integration maintained in separate work with agent handoff instructions; names / IDs are incomplete.')],['Codex · 2026-10-11',bi('本次檔案與 docs/verification','This delivery and docs/verification'),bi('本輪未啟動子 agent，不能將建議平行流程當成執行紀錄。','No subagents were spawned this turn; suggested parallel work is not an execution record.')]])+para('建議可重用分工：設計 agent 寫 SPEC，收音 agent 管輸入契約，素材 agent 管 manifest／授權，整合 agent 接模組，驗收 agent 保留實測證據。分配不重疊檔案與明確交付；BLOCKED、缺圖、未真機驗收皆保留未完成狀態。','Reusable suggested roles: design owns SPEC; audio owns input contracts; assets own manifests / rights; integration connects modules; verification preserves evidence. Assign nonoverlapping files and explicit deliverables. BLOCKED, missing images and untested hardware remain incomplete.')+mermaid_block('handoff','建議協作流程（非歷史執行紀錄）','Suggested collaboration (not a historical execution record)')))
original=(R/'assets/pencil-cartoon/GENERATION-PROMPTS.md').read_text(encoding='utf-8'); prompt=original.split('```text\n')[1].split('```')[0]
parts.append(section('prompts','提示詞與交接','Prompts and handoffs',para('以下英文保留 GENERATION-PROMPTS.md 的可重用原文；不宣稱每一次歷史呼叫都逐字如此。中文摘要是同義操作說明。','The English block preserves the reusable text in GENERATION-PROMPTS.md; not a claim about every historical call. The Chinese block summarizes the same operation.')+'<div class="en">'+code(prompt)+'</div><div class="zh">'+code('原圖是唯一編輯目標，麻雀圖僅供風格參考，不可加入其他物種。\n童書色鉛筆、圓潤溫暖，保持物種特徵、姿勢、朝向、完整輪廓與比例。\n鳥：單隻、真透明、無文字道具或其他鳥；場景：保持地形植被建物座標，滿版不透明，不新增動物。\n逐張查看來源；鳥 transparent_background=true，場景 false。\n保留 generatedSource，manifest 管理來源、輸出與驗收；只續作 pending/invalid。')+'</div>'+'<h3>'+bi('新增 STEM 建置提示模板','New STEM build prompt template')+'</h3>'+code('Read MotionPad-STEM-Agent/AGENTS.md and skills/motionpad-stem/SKILL.md.\nBuild a [topic] game using panorama + viewfinder, normalized targets, JSON levels, persistent collection and 3×3 input.\nKeep 5 as rest; 2/8/4/6 movement; 7/1 zoom; 9 capture/confirm; 3 exit/cancel; 1+7 equipment switching.\nReuse audio-core/audio-receiver for microphone-based ultrasonic input; protocol frequencies are calibratable defaults.\nInclude keyboard/touch fallback, calibration, speaker low-pass, licensed assets and foot-operable exits.\nDeliver SPEC, source, asset/model ledger, actual test evidence and unverified hardware limitations.')+para('接續時記錄完成項目、負責檔案、操作契約、待辦、素材來源、測試指令及實際結果；模型名稱未知就填 unknown。agent/references/HANDOFF.md 提供範本。','Handoffs record completed work, owned files, input contracts, pending items, asset sources, test commands and actual results; unknown model names remain unknown. The bundle provides references/HANDOFF.md.')))
parts.append(section('frameworks','框架、建置與驗收','Frameworks, builds and verification',table([bi('技術','Technology'),bi('工作區版本／用途','Workspace version / use')],[['JavaScript / HTML / CSS / Canvas 2D',bi('ES Modules、原生瀏覽器 API，不需前端 bundler。','ES Modules and native browser APIs; no frontend bundler.')],['Web Audio / MediaDevices',bi('MIDI、鳥鳴解碼、FFT 與麥克風。','MIDI, recording decoding, FFT and microphone capture.')],['Electron',bi('desktop/package.json：^37.2.0；@electron/packager ^18.3.6。','desktop/package.json: ^37.2.0; @electron/packager ^18.3.6.')],['Capacitor',bi('Android／Core／CLI ^7.4.2；App ^7.1.2。','Android / Core / CLI ^7.4.2; App ^7.1.2.')],['Python / Pillow / NumPy / FFmpeg',bi('關卡、素材、頻譜工具；本次錄音用 FFmpeg。依各工具 import 準備環境。','Level, asset and spectrum tools; calls processed with FFmpeg. Prepare dependencies according to tool imports.')],['Inno Setup',bi('installer/bird-view.iss 建 Windows 安裝檔。','installer/bird-view.iss builds Windows installers.')],['Mermaid 9.4.3',bi('僅文件，本地 vendor、MIT；靜態 SVG 可離線閱讀。','Documentation only, locally vendored under MIT; static SVGs work offline.')]])+code('python -m http.server 8080 --bind 127.0.0.1\n# http://localhost:8080/\npython tools/check_level.py data/levels/level01.json\npython tools/stage_web.py --with-test-audio\ncd desktop\nnpm run selftest\n.\\node_modules\\.bin\\electron.cmd . --selftest=soundscape\n# Production packaging: restage WITHOUT reference test WAVs\ncd ..\npython tools/stage_web.py\ncd desktop\nnpm run package\n# Android: stage -> npm run sync in android-app -> Gradle build/sign')+para('驗收由素材與 hash、每關匹配、解碼、靜音／切關／失敗備援，到參考音檔模擬、真機現場量測分層執行。本輪結果存於 docs/verification/report.json。舊 EXE／APK 不含新鳥鳴，發行需另重建。','Validate assets / hashes, per-level matching, decoding, mute / switching / failure fallback, reference-audio simulation, then field measurements. Results are in docs/verification/report.json. Existing EXE / APK files lack the new calls and require rebuilding for release.')))
reuse=[('星空觀測','Stargazing','全景天空＋望遠鏡，單一星體入鏡','Sky panorama + telescope, one object per frame','角度、視野、倍率','Angles, field of view, magnification'),('海洋／昆蟲觀察','Marine / insect observation','替換場景與 species，保留圖鑑、stay 與拍照','Replace scenes / species; retain collection, stay and capture','棲地、分類、生物多樣性','Habitat, taxonomy, biodiversity'),('聲音偵探','Sound detective','有來源音檔，辨音後尋找目標','Attributed clips, identify a sound and find its target','頻率、聲波、訊雜比','Frequency, waves, signal-to-noise ratio'),('數學尋寶／物流','Math hunt / logistics','座標框選、JSON 關卡、9 確認','Coordinate selection, JSON levels, 9 confirms','比例、座標、路徑','Ratios, coordinates, routes'),('反應與節奏','Reaction and rhythm','離散踩踏、5 休息、可退出','Discrete steps, cell 5 rest, reachable exit','時間、取樣、延遲','Time, sampling, latency')]
parts.append(section('reuse','其他遊戲與 STEM 延伸','Other games and STEM extensions',table([bi('主題','Topic'),bi('沿用模式','Reusable pattern'),bi('STEM 概念','STEM concept')],[[bi(z,en),bi(a,b),bi(c,d)] for z,en,a,b,c,d in reuse])+para('先換資料與素材，再調動作映射；八頻道地墊不能推定壓力、格內位置、滑動、左右腳。節奏時窗需現場量測，不以鍵盤速度代替。','Replace data and assets before adapting actions. Eight-channel input does not establish pressure, within-cell position, sliding or left/right foot. Rhythm windows need field measurements, not keyboard speed estimates.')))
parts.append(section('bundle','MotionPad-STEM-Agent 可攜套件','MotionPad-STEM-Agent portable bundle',para('依指定名稱建立資料夾，內容為「相容於 MotionPad 的 STEM 開發助手」，不代表官方產品或背書。純 Markdown 可供不同 coding agent 讀取，SKILL.md 供支援 Agent Skills 的宿主載入；各平台自動發現路徑不相同，README 提供使用方式。','The requested folder contains a STEM development assistant compatible with MotionPad, without official endorsement. Plain Markdown works with different coding agents and SKILL.md with Agent Skills hosts. Discovery paths differ by platform; README explains usage.')+code('MotionPad-STEM-Agent/\n  AGENTS.md / CLAUDE.md / GEMINI.md / README.md\n  skills/motionpad-stem/SKILL.md\n  references/architecture.md / hardware.md / prompts.md / HANDOFF.md\n  reference-runtime/js/ + audio-protocol/protocol.json\n  examples/stem-observer/index.html\n  scripts/serve.py / validate.py\n  .github/copilot-instructions.md\n  provenance.json / NOTICE.md')+para('只收 BirdView 自有模組與新摘要，不複製受邀 Genius Holdings 工具包、mat/vendor、mat/profiles、簽章金鑰或私人聊天。若使用外部宿主／bridge，依合法取得的原規範操作；不要把 BirdView 20 ms 接收迴圈與工具包 hop 契約當成同一套硬體實測。','Contains BirdView workspace modules and new summaries, not the invited Genius Holdings toolkit, mat/vendor, mat/profiles, signing keys or private chats. External hosts / bridges require legitimately obtained original instructions. BirdView’s 20 ms receiver loop is distinct from an external toolkit’s hop contract.')+'<p><a href="MotionPad-STEM-Agent/README.md">'+bi('使用說明','Usage guide')+'</a> · <a href="MotionPad-STEM-Agent/examples/stem-observer/index.html">'+bi('STEM 範例','STEM demo')+'</a></p>'))
