if report_path.exists():
 report=json.loads(report_path.read_text(encoding='utf-8'))
 parts.append(section('verification','本輪實際驗證結果','Actual verification results',table([bi('檢查','Check'),bi('結果與證據','Result / evidence')],[[name,('PASS' if row['ok'] else 'FAIL')+' · <a href="docs/verification/'+row['evidence']+'">'+row['evidence']+'</a>'] for name,row in report['results'].items()])+para('音景 23 項、文件／STEM UI 15 項、十關檢查、標準音量八格與遊戲模擬均通過。−10 dB 低訊號診斷僅 6／8 格單次正確觸發；不是完整弱訊號驗收。真地墊與 Android 麥克風未測；既有 EXE／APK 未重建。','23 soundscape checks, 15 document / STEM UI checks, ten levels, eight standard-level channels and simulated gameplay passed. Minus-10-dB diagnostics achieved correct single triggering on only 6/8 channels, so weak-signal acceptance is incomplete. Physical mats and Android microphones remain untested; existing EXE / APK files were not rebuilt.')))
css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:#f6f4ed;color:#233d31;font:16px/1.75 system-ui,"Microsoft JhengHei",sans-serif}.en{display:none}html[lang=en] .zh{display:none}html[lang=en] .en{display:revert}a{color:#245e4a}header{background:#234e3c;color:#fff;padding:75px max(5vw,20px) 45px}header h1{font-size:clamp(32px,5vw,58px);line-height:1.2;margin:12px 0}header p{max-width:850px;color:#e4eadd}.eyebrow{letter-spacing:.2em;font-size:12px}.lang{position:fixed;right:16px;top:14px;z-index:10;background:#fff;border-radius:12px;box-shadow:0 3px 18px #0002;padding:5px;display:flex;gap:4px}.lang button{cursor:pointer;border:0;background:transparent;color:#234e3c;padding:9px 14px;border-radius:8px}.lang button[aria-pressed=true]{background:#234e3c;color:white}nav{position:sticky;top:0;z-index:5;background:#faf9f2f2;padding:14px 20px;display:flex;gap:18px;overflow:auto;border-bottom:1px solid #ddd}nav a{white-space:nowrap;text-decoration:none;font-size:14px}main{max-width:1200px;margin:auto;padding:24px}section{margin:28px 0;padding:28px;background:white;border-radius:20px;border:1px solid #e6e9df}h2{font-size:28px;line-height:1.35;margin:0 0 22px}h3{font-size:20px}p{max-width:100ch}.two{display:grid;grid-template-columns:1fr 1fr;gap:24px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:12px;vertical-align:top;border-bottom:1px solid #e2e7dd}th{background:#eef3e9}td:first-child{min-width:110px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#18392d;color:#e3f1e8;padding:20px;border-radius:12px;font:13px/1.7 ui-monospace,monospace}svg{width:100%;height:auto}svg text{fill:#233d31;font:15px system-ui,sans-serif}svg .svgnum{font-size:24px;font-weight:700}audio{display:block;width:240px;max-width:100%;margin-top:10px}.mermaid{overflow:auto;padding:16px;border:1px solid #e0e6d9;border-radius:12px}details{margin-top:16px}summary{cursor:pointer}footer{max-width:1200px;margin:auto;padding:35px;color:#5e6e62}@media(max-width:760px){main{padding:12px}section{padding:20px}.two{grid-template-columns:1fr}h2{font-size:23px}svg text{font-size:13px}}@media print{.lang,nav,audio{display:none}header{padding:25px;color:#233d31;background:none}section{break-inside:avoid}pre{color:#233d31;background:#eef3e9}}'''
diagrams={
'zh':{'flow':'flowchart LR\n K[鍵盤與觸控] --> I[input.press]\n M[地墊高頻音] --> R[audio-receiver]\n R --> I\n I --> G[main 遊戲流程]\n D[關卡 JSON 與圖片] --> G\n G --> C[鏡頭與攝影]\n C --> P[localStorage 圖鑑]\n G --> V[全景與鏡頭渲染]\n G --> S[MIDI 與鳥鳴]','detector':'stateDiagram-v2\n [*] --> locked\n locked --> armed: 低於閾值乘0.6持續80ms\n armed --> confirming: 超過閾值\n confirming --> armed: 訊號不足\n confirming --> trigger: 確認40ms且單格\n confirming --> conflict: 多格超標\n trigger --> locked\n conflict --> locked','handoff':'flowchart LR\n A[需求與SPEC] --> B[收音與輸入契約]\n A --> C[素材與授權manifest]\n B --> D[整合agent]\n C --> D\n D --> E[驗收agent與證據]\n E --> F[交接與交付]'},
'en':{'flow':'flowchart LR\n K[Keyboard and touch] --> I[input.press]\n M[Mat ultrasonic tones] --> R[audio-receiver]\n R --> I\n I --> G[main game flow]\n D[Level JSON and images] --> G\n G --> C[Camera and capture]\n C --> P[localStorage collection]\n G --> V[Panorama and viewfinder]\n G --> S[MIDI and bird calls]','detector':'stateDiagram-v2\n [*] --> locked\n locked --> armed: Below threshold x 0.6 for 80ms\n armed --> confirming: Above threshold\n confirming --> armed: Signal drops\n confirming --> trigger: 40ms single cell\n confirming --> conflict: Multiple active cells\n trigger --> locked\n conflict --> locked','handoff':'flowchart LR\n A[Requirements and SPEC] --> B[Audio and input contract]\n A --> C[Assets and license manifest]\n B --> D[Integration agent]\n C --> D\n D --> E[Verification agent and evidence]\n E --> F[Handoff and delivery]'}}
js='const diagrams='+json.dumps(diagrams,ensure_ascii=False)+';'+'''
let rendering=Promise.resolve();
function setLanguage(lang){document.documentElement.lang=lang==='en'?'en':'zh-Hant';document.title=lang==='en'?'BirdView — Development & STEM Agent':'走，賞鳥趣 — 開發紀錄與 STEM Agent';document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));try{localStorage.setItem('birdview-doc-lang',lang)}catch{} rendering=rendering.then(async()=>{if((document.documentElement.lang==='en'?'en':'zh')!==lang)return;for(const id of ['flow','detector','handoff']){const node=document.getElementById(id);node.textContent=diagrams[lang][id];node.removeAttribute('data-processed');document.getElementById(id+'Source').textContent=diagrams[lang][id];if(window.mermaid){try{await mermaid.init(undefined,node)}catch(e){node.textContent=diagrams[lang][id]}}}})}
if(window.mermaid)mermaid.initialize({startOnLoad:false,securityLevel:'strict',theme:'neutral'});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
let saved='zh';try{saved=localStorage.getItem('birdview-doc-lang')||saved}catch{}setLanguage(saved==='en'?'en':'zh');
'''
nav=[('overview','現況','Status'),('play','玩法','Play'),('architecture','架構','Architecture'),('hardware','地墊','Hardware'),('calls','鳥鳴','Calls'),('levels','關卡','Levels'),('history','開發','Process'),('agents','AI 協作','AI teams'),('prompts','提示詞','Prompts'),('frameworks','建置','Build'),('reuse','延伸','Reuse'),('bundle','Agent','Agent'),('verification','驗證','Verification')]
page='<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>走，賞鳥趣 — 開發紀錄與 STEM Agent</title><style>'+css+'</style></head><body><div class="lang" role="group" aria-label="Language / 語言"><button data-lang="zh" aria-pressed="true">繁體中文</button><button data-lang="en" aria-pressed="false">English</button></div><header><div class="eyebrow">BIRDVIEW · DEVELOPMENT NOTEBOOK · 2026-10-11</div><h1>'+bi('從賞鳥遊戲到<br>可重用的 STEM 開發助手','From birdwatching to<br>a reusable STEM coding assistant')+'</h1>'+para('玩法、架構、超聲波地墊、開放鳥鳴與多 AI 協作，一份可離線閱讀的開發紀錄。','Gameplay, architecture, ultrasonic input, open calls and multi-AI collaboration in an offline development record.')+'</header><nav>'+''.join('<a href="#'+id+'">'+bi(z,en)+'</a>' for id,z,en in nav)+'</nav><main>'+''.join(parts)+'</main><footer>'+bi('依本工作區檔案整理；錄音授權各自保留。無遠端字型與執行時 CDN。','Based on workspace files; recordings retain their licenses. No remote fonts or runtime CDN.')+' <a href="docs/vendor/mermaid-LICENSE.txt">Mermaid 9.4.3 · MIT</a></footer><script src="docs/vendor/mermaid.min.js"></script><script>'+js+'</script></body></html>'
(R/'bird-view-development.html').write_text(page,encoding='utf-8')
creditpage='<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BirdView 鳥鳴來源 / Call credits</title><style>'+css+'.en{display:inline} .zh:after{content:" / "}</style><body><main><h1>鳥鳴來源 / Bird call credits</h1><p>開放授權錄音與衍生檔 / Open recordings and derivatives. Retrieved 2026-10-11.</p>'+credits.replace('src="assets/bird-calls/','src="')+'<p>原始與衍生檔 hash、來源與變更見 <a href="manifest.json">manifest.json</a>；<a href="CC-BY-SA-3.0.html">CC BY-SA 3.0</a> / <a href="CC-BY-SA-4.0.html">CC BY-SA 4.0</a>；衍生音檔沿用各自 CC BY-SA 授權。<br>Hashes and transformations are in the manifest. Derivatives retain source CC BY-SA.</p><p><a href="../../index.html">返回遊戲 / Back to game</a></p></main></body></html>'
(R/'assets/bird-calls/CREDITS.html').write_text(creditpage,encoding='utf-8')
